MATCH (loop:ProcessInstrumentationFunction {loop_tag: 'LSHH-37002'})-[:send_signal_to*]->(actuator:PlantItem {kind: 'actuator'})-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
