MATCH (a:PlantItem {tag: 'EA-2901'}), (b:PlantItem {tag: 'P-3101'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'V-2901' AND y.tag <> 'V-2901')+ (b)
}
RETURN b.tag AS tag

MATCH (a:PlantItem {tag: 'E-201'}), (b:PlantItem {tag: 'EH-201'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE NONE(n IN nodes(p) WHERE n.tag = 'TV-2044')
       } AS reachable_without_TV_2044

